from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_closes = []
        self.spy_close = None
        self.spy_sma = None
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_avg_gain = None
        self.rsi_avg_loss = None
        self.aapl_rsi = None
        self.aapl_previous_rsi = None

        self.lots = {
            1: {"symbol": self.spy, "shares": 0},
            2: {"symbol": self.aapl, "shares": 0},
        }

        self.owner = None
        self.pending_orders = {}

    def OnData(self, data):
        self._update_state(data)

        required = [self.spy, self.aapl]
        for symbol in self.symbols.values():
            if symbol not in data.Bars:
                return

        if self.IsWarmingUp:
            return

        if self.owner is not None:
            if self.lots[self.owner]["shares"] == 0 and self.owner not in self.pending_orders:
                self.owner = None
                return

            if self.owner == 1:
                if self._spy_crosses_below_sma():
                    self._sell_lot(1)
            elif self.owner == 2:
                if self.aapl_rsi is not None and self.aapl_rsi > 60:
                    self._sell_lot(2)

            return

        if self.lots[1]["shares"] > 0 or self.lots[2]["shares"] > 0:
            return

        if not self._all_rules_ready():
            return

        if self._spy_crosses_above_sma():
            quantity = int(
                (0.40 * float(self.Portfolio.TotalPortfolioValue))
                / float(data.Bars[self.spy].Close)
            )
            if quantity > 0:
                self.owner = 1
                self._buy_lot(1, quantity)
                return

        if self.aapl_red_streak >= 3:
            close = float(data.Bars[self.aapl].Close)
            if float(self.Portfolio.Cash) >= 20000:
                quantity = int(20000 / close)
                if quantity > 0:
                    self.owner = 2
                    self._buy_lot(2, quantity)

    def _update_state(self, data):
        if self.spy in data.Bars:
            close = float(data.Bars[self.spy].Close)

            self.spy_previous_close = self.spy_close
            self.spy_previous_sma = self.spy_sma
            self.spy_close = close
            self.spy_closes.append(close)

            if len(self.spy_closes) >= 100:
                self.spy_sma = sum(self.spy_closes[-100:]) / 100.0

        if self.aapl in data.Bars:
            close = float(data.Bars[self.aapl].Close)

            if self.aapl_close is not None:
                if close < self.aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_close = close

            self.aapl_previous_rsi = self.aapl_rsi
            self._update_rsi(close)

    def _update_rsi(self, close):
        if not hasattr(self, "_rsi_previous_close"):
            self._rsi_previous_close = close
            return

        change = close - self._rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        self._rsi_previous_close = close

        if self.rsi_count < self.rsi_period:
            self.rsi_gain_sum += gain
            self.rsi_loss_sum += loss
            self.rsi_count += 1

            if self.rsi_count == self.rsi_period:
                self.rsi_avg_gain = self.rsi_gain_sum / self.rsi_period
                self.rsi_avg_loss = self.rsi_loss_sum / self.rsi_period
                self.aapl_rsi = self._calculate_rsi()
            return

        self.rsi_avg_gain = (
            (self.rsi_avg_gain * (self.rsi_period - 1)) + gain
        ) / self.rsi_period
        self.rsi_avg_loss = (
            (self.rsi_avg_loss * (self.rsi_period - 1)) + loss
        ) / self.rsi_period
        self.aapl_rsi = self._calculate_rsi()

    def _calculate_rsi(self):
        if self.rsi_avg_loss == 0:
            return 100.0
        if self.rsi_avg_gain == 0:
            return 0.0

        relative_strength = self.rsi_avg_gain / self.rsi_avg_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def _all_rules_ready(self):
        return (
            len(self.spy_closes) >= 101
            and self.spy_previous_sma is not None
            and self.spy_sma is not None
            and self.rsi_count >= self.rsi_period
            and self.aapl_rsi is not None
            and self.aapl_red_streak >= 3
        )

    def _spy_crosses_above_sma(self):
        return (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_close is not None
            and self.spy_sma is not None
            and self.spy_previous_close <= self.spy_previous_sma
            and self.spy_close > self.spy_sma
        )

    def _spy_crosses_below_sma(self):
        return (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_close is not None
            and self.spy_sma is not None
            and self.spy_previous_close >= self.spy_previous_sma
            and self.spy_close < self.spy_sma
        )

    def _buy_lot(self, slot, quantity):
        if slot in self.pending_orders:
            return

        symbol = self.lots[slot]["symbol"]
        order = self.MarketOrder(symbol, quantity, tag="SLOT{}_BUY".format(slot))
        self.pending_orders[slot] = order.OrderId

    def _sell_lot(self, slot):
        if slot in self.pending_orders:
            return

        shares = self.lots[slot]["shares"]
        if shares <= 0:
            return

        symbol = self.lots[slot]["symbol"]
        order = self.MarketOrder(symbol, -shares, tag="SLOT{}_SELL".format(slot))
        self.pending_orders[slot] = order.OrderId

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId
        slot = None

        for candidate_slot, candidate_order_id in self.pending_orders.items():
            if candidate_order_id == order_id:
                slot = candidate_slot
                break

        if slot is None:
            return

        self.lots[slot]["shares"] += int(order_event.FillQuantity)

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        ]:
            if order_event.Status != OrderStatus.PartiallyFilled:
                del self.pending_orders[slot]
